/* Generate static Aura theme CSS for the prototype (PrimeNG-first policy).
   Pulls the REAL Aura preset + per-component base styles from the ISC
   node_modules (same versions the Angular port renders with) and emits
   vendor/aura.css: layer order + common vars + per-component base+theme CSS.

   Run:  node generate-aura.mjs   (re-run after ISC PrimeNG upgrades)
   Components list = the PrimeNG surface the distribution proto uses. */
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ISC_NM = '/Users/billklingensmith/Code/ideal-sale-circular/node_modules';
const { Theme, $dt } = await import(join(ISC_NM, '@primeuix/styled/dist/index.mjs'));
const Aura = (await import(join(ISC_NM, '@primeuix/themes/dist/aura/index.mjs'))).default;

const COMPONENTS = [
  'button', 'chip', 'skeleton', 'popover', 'carousel', 'datepicker',
  'select', 'selectbutton', 'togglebutton', 'multiselect',
  'datatable', 'treetable', 'paginator', 'checkbox', 'iconfield', 'inputtext',
];

// Mirrors ISC app.module.ts providePrimeNG: plain Aura, darkModeSelector: false.
Theme.setTheme({ preset: Aura, options: { prefix: 'p', darkModeSelector: false, cssLayer: false } });

const stripTags = (s) => String(s || '').replace(/<\/?style[^>]*>/g, '\n');
// Base styles reference tokens as dt('a.b.c') — resolve to var(--p-a-b-c)
// exactly like the PrimeNG runtime does ($dt handles camelCase→dash-case).
const resolveDt = (css) => css.replace(/dt\(\s*'([^']+)'\s*(?:,\s*'([^']*)'\s*)?\)/g, (_, token, fallback) => {
  const v = $dt(token).variable;
  return fallback ? v.replace(')', `, ${fallback})`) : v;
});
let out = '/* AUTO-GENERATED by generate-aura.mjs — do not hand-edit. */\n';
out += stripTags(Theme.getCommonStyleSheet());

for (const name of COMPONENTS) {
  let base = '';
  try {
    base = (await import(join(ISC_NM, `@primeuix/styles/dist/${name}/index.mjs`))).style;
  } catch (e) {
    console.warn(`no base style for ${name}: ${e.message}`);
  }
  out += `\n/* ── ${name} ── */\n`;
  if (base) out += resolveDt(String(base));
  out += stripTags(Theme.getStyleSheet(name));
}

const leftover = (out.match(/dt\(/g) || []).length;
if (leftover) console.warn(`WARNING: ${leftover} unresolved dt() tokens remain`);

const dest = join(dirname(fileURLToPath(import.meta.url)), 'aura.css');
writeFileSync(dest, out);
console.log(`wrote ${dest} (${(out.length / 1024).toFixed(1)} KB)`);
